  collect: () => require('shopify-api-node/resources/collect'),
  collection: () => require('shopify-api-node/resources/collection'),
  collectionListing: () => require('shopify-api-node/resources/collection-listing'),
  comment: () => require('shopify-api-node/resources/comment'),
  country: () => require('shopify-api-node/resources/country'),
  currency: () => require('shopify-api-node/resources/currency'),
  customCollection: () => require('shopify-api-node/resources/custom-collection'),
  customer: () => require('shopify-api-node/resources/customer'),
  customerAddress: () => require('shopify-api-node/resources/customer-address'),
  customerSavedSearch: () => require('shopify-api-node/resources/customer-saved-search'),
