  fulfillment: () => require('shopify-api-node/resources/fulfillment'),
  fulfillmentEvent: () => require('shopify-api-node/resources/fulfillment-event'),
  fulfillmentOrder: () => require('shopify-api-node/resources/fulfillment-order'),
  fulfillmentRequest: () => require('shopify-api-node/resources/fulfillment-request'),
  fulfillmentService: () => require('shopify-api-node/resources/fulfillment-service'),
  giftCard: () => require('shopify-api-node/resources/gift-card'),
  giftCardAdjustment: () => require('shopify-api-node/resources/gift-card-adjustment'),
  inventoryItem: () => require('shopify-api-node/resources/inventory-item'),
  inventoryLevel: () => require('shopify-api-node/resources/inventory-level'),
  location: () => require('shopify-api-node/resources/location'),
  marketingEvent: () => require('shopify-api-node/resources/marketing-event'),
  metafield: () => require('shopify-api-node/resources/metafield'),
  order: () => require('shopify-api-node/resources/order'),
  orderRisk: () => require('shopify-api-node/resources/order-risk'),
  page: () => require('shopify-api-node/resources/page'),
  payment: () => require('shopify-api-node/resources/payment'),
  payout: () => require('shopify-api-node/resources/payout'),
